// @ts-nocheck
// Hairline figure "lamp" for hollis-brandt-lighthouse-4s. Generated by the murder-mystery-story-tree skill via hairline-create.
// Body is the figure file verbatim; edit with: python scripts/art.py unwrap <this> lamp.js → look.mjs → wrap.
export default function define(HL, hairline) {
/**
 * Lamp: a lighthouse lens, a ring of eight prism panels on a round plinth.
 * One panel is blacked out: plain glass, no cut line. At rest the one bright
 * mark sits on that dark panel. The pointer's angle round the ring picks the
 * panel the beam falls on; the bright mark goes there and leaves the dark one.
 *
 * The pattern: discrete items. A hit test by rest angle on the ground plane,
 * which never moves; the frame loop only redraws on change.
 */
const { Cam, fit, prism, proj, facing, rings, unproj, mk, place, pointer, put, disposer, solid, register } = HL;

const N = 8, RAD = 40, S = 9, PH = 36, DARK = 0, A0 = 20;
const ang = (k) => ((A0 + (360 / N) * k) * Math.PI) / 180;

function mount({ stage, svg, read }) {
  const bag = disposer();
  const C = Cam(45, 0.5, 1.9);
  fit(C, [[-62, -62, -6], [62, 62, -6], [62, -62, -6], [-62, 62, -6], [0, 0, PH + 4]], 200, 166);
  const P = proj(C), front = facing(C);
  const g = mk("g", {}, svg);
  const [br, bi] = rings(-60, -60, 60, 60, 24, 2.2);
  put(solid(g), prism(P, front, br, bi, -6, 0));

  // painted far to near: ascending x + y
  const panels = [];
  for (let k = 0; k < N; k++) panels.push({ k, x: RAD * Math.cos(ang(k)), y: RAD * Math.sin(ang(k)) });
  panels.slice().sort((a, b) => a.x + a.y - (b.x + b.y)).forEach((p) => {
    const [r, i] = rings(p.x - S, p.y - S, p.x + S, p.y + S, 4, 1.4);
    p.el = solid(g);
    put(p.el, prism(P, front, r, i, 0, PH));
    if (p.k === DARK) p.el.cr.setAttribute("d", ""); // plain glass: no cut line
    p.dot = mk("circle", { r: 2.4, class: "dot" }, p.el.g);
    place(p.dot, P(p.x, p.y, PH));
  });

  const byK = panels.slice().sort((a, b) => a.k - b.k);
  function lit(a) {
    byK.forEach((p) => {
      const on = p.k === a;
      p.el.sil.classList.toggle("hi", on);
      p.dot.setAttribute("class", on ? "dot" : "dot off");
    });
  }
  let want = DARK, shown = -1;
  const B = register(stage, () => { if (want !== shown) { shown = want; lit(want); } return false; });
  bag.add(B.unregister);
  const go = (a, text) => { want = a; read.textContent = text; B.wake(); };
  read.textContent = "rest";

  bag.add(pointer(stage, {
    move: (p) => {
      const [x, y] = unproj(C, p[0], p[1], 0);
      const t = (Math.atan2(y, x) * 180) / Math.PI - A0;
      const a = ((Math.round(t / (360 / N)) % N) + N) % N;
      go(a, a === DARK ? "dark" : "beam");
    },
    leave: () => go(DARK, "rest"),
  }));
  bag.add(() => svg.replaceChildren());
  return { set: () => {}, destroy: bag.dispose };
}

hairline({
  name: "lamp",
  means: "A ring of lens panels: the beam falls on the one the pointer faces, and one panel is dark.",
  rules: [1, 5, 9, 10],
  range: [0, 0.5, 1],
  tour: [[129, 143], [226, 120], [271, 169], [174, 192], [232, 191], null],
  mount,
});
}
